                      "MPL-2.0", "0BSD", "Unlicense", "CC0-1.0"}


class Report:
    def __init__(self):
        self.items = []

    def fail(self, path, msg):
        self.items.append(("FAIL", path, msg))

    def warn(self, path, msg):
        self.items.append(("WARN", path, msg))

    @property
    def fails(self):
        return [i for i in self.items if i[0] == "FAIL"]

    def print(self):
        for status, path, msg in self.items:
            print(f"{status:5} {path:55} {msg}")
        print(f"\nSummary: {len(self.fails)} FAIL, "
              f"{len(self.items) - len(self.fails)} WARN, "
              f"{len(self.items)} total findings")


