            rep.fail("creationInfo.created", "required field missing")
        elif not CREATED_RE.fullmatch(ci["created"]):
            rep.fail("creationInfo.created", "must be ISO 8601 UTC: YYYY-MM-DDThh:mm:ssZ")
        creators = ci.get("creators")
        if not isinstance(creators, list) or not creators:
            rep.fail("creationInfo.creators", "required: at least one creator")
        else:
            for i, c in enumerate(creators):
                if not CREATOR_RE.fullmatch(c):
                    rep.fail(f"creationInfo.creators[{i}]",
                             f"{c!r} must start with 'Person:', 'Organization:' or 'Tool:'")
        llv = ci.get("licenseListVersion")
        if llv is not None and not re.fullmatch(r"\d+\.\d+", str(llv)):
            rep.fail("creationInfo.licenseListVersion", f"{llv!r} must be '<major>.<minor>'")
    else:
        rep.fail("creationInfo", "required object missing")

    # ---- collect SPDX IDs, uniqueness ----
    all_ids = ["SPDXRef-DOCUMENT"]
    packages = doc.get("packages", [])
    files = doc.get("files", [])
    for p in packages:
        all_ids.append(p.get("SPDXID", ""))
    for f in files:
        all_ids.append(f.get("SPDXID", ""))
    dupes = {i for i in all_ids if all_ids.count(i) > 1}
    if dupes:
        rep.fail("document", f"duplicate SPDXIDs: {sorted(dupes)}")

    # ---- packages ----
    for pi, p in enumerate(packages):
        path = f"packages[{pi}]"
        if not p.get("SPDXID"):
            rep.fail(f"{path}.SPDXID", "required field missing")
        elif not SPDXID_RE.fullmatch(p["SPDXID"]):
            rep.fail(f"{path}.SPDXID", f"invalid SPDX ID {p['SPDXID']!r}")
        if not p.get("name"):
            rep.fail(f"{path}.name", "required field missing")
        if "downloadLocation" not in p:
            rep.fail(f"{path}.downloadLocation", "required field missing (may be NOASSERTION)")
        if "filesAnalyzed" not in p:
            rep.fail(f"{path}.filesAnalyzed", "required field missing")
        if "licenseConcluded" not in p:
            rep.fail(f"{path}.licenseConcluded", "required field missing (may be NOASSERTION)")
        if "licenseDeclared" not in p:
            rep.fail(f"{path}.licenseDeclared", "required field missing (may be NOASSERTION)")
        if "copyrightText" not in p:
            rep.fail(f"{path}.copyrightText", "required field missing (may be NOASSERTION)")

        fa = p.get("filesAnalyzed")
        vc = p.get("verificationCode")
        if fa is True:
            # REQUIRED when filesAnalyzed == true
            if not isinstance(vc, dict) or not vc.get("packageVerificationCodeValue"):
                rep.fail(f"{path}.verificationCode",
                         "REQUIRED when filesAnalyzed is true")
            else:
                val = vc.get("packageVerificationValue", vc.get("packageVerificationCodeValue", ""))
                if not SHA1_RE.fullmatch(val):
                    rep.fail(f"{path}.verificationCode.packageVerificationCodeValue",
                             "must be a 40-char lowercase hex SHA1")
        elif fa is False and vc is not None:
            rep.fail(f"{path}.verificationCode",
                     "must NOT be present when filesAnalyzed is false")

        for fi, c in enumerate(p.get("checksums", [])):
            valid_checksum(f"{path}.checksums[{fi}]", c.get("algorithm"), c.get("checksumValue"), rep)
        for role in ("supplier", "originator"):
            v = p.get(role)
            if v is not None and not CREATOR_RE.fullmatch(v):
                rep.fail(f"{path}.{role}", f"{v!r} must start with 'Person:' or 'Organization:'")

    # ---- files ----
    for fi, f in enumerate(files):
        path = f"files[{fi}]({f.get('fileName', '?')})"
        if not f.get("fileName"):
            rep.fail(f"{path}.fileName", "required field missing")
        if not f.get("SPDXID"):
            rep.fail(f"{path}.SPDXID", "required field missing")
        elif not SPDXID_RE.fullmatch(f["SPDXID"]):
            rep.fail(f"{path}.SPDXID", f"invalid SPDX ID {f['SPDXID']!r}")
        cs = f.get("checksums")
        if not isinstance(cs, list) or not cs:
            rep.fail(f"{path}.checksums", "required: at least one checksum")
        else:
            for ci_, c in enumerate(cs):
                if not valid_checksum(f"{path}.checksums[{ci}]", c.get("algorithm"),
                                      c.get("checksumValue"), rep):
                    pass
        if "licenseConcluded" not in f:
            rep.fail(f"{path}.licenseConcluded", "required field missing (may be NOASSERTION)")
        if "copyrightText" not in f:
            rep.fail(f"{path}.copyrightText", "required field missing (may be NOASSERTION)")
        li = f.get("licenseInfoInFiles")
        if not isinstance(li, list) or not li:
            rep.fail(f"{path}.licenseInfoInFiles",
                     "required non-empty array (may be ['NOASSERTION'])")
        for ft in f.get("fileTypes", []):
            if ft not in ALLOWED_FILE_TYPES:
                rep.fail(f"{path}.fileTypes", f"unknown file type {ft!r}")

        # disk integrity: checksum + license evidence claims vs real files
        fname = (f.get("fileName") or "").lstrip("./")
        try:
            data = open(fname, "rb").read()
        except OSError:
            rep.warn(f"{path}", f"file {fname!r} not found on disk for integrity check")
            continue
        if disk_files:
            for c in cs or []:
                algo = c.get("algorithm")
                if algo == "SHA1":
                    actual = hashlib.sha1(data).hexdigest()
                elif algo == "SHA256":
                    actual = hashlib.sha256(data).hexdigest()
                else:
                    continue
                if c.get("checksumValue") != actual:
                    rep.fail(f"{path}.checksums[{ci_}]({algo})",
                             f"checksum mismatch vs disk: got {c.get('checksumValue')}, "
                             f"expected {actual}")
            # evidence cross-checks
            ev = f.get("evidence", {})
            for pfe in ev.get("packageFileEvidence", []):
                if pfe.get("fileName") not in (None, f.get("fileName")):
                    rep.warn(f"{path}.evidence.packageFileEvidence",
                             f"evidence fileName {pfe.get('fileName')!r} != component")
                for c in pfe.get("fileChecksums", []):
                    algo = c.get("algorithm")
                    actual = {"SHA1": hashlib.sha1(data).hexdigest(),
                              "SHA256": hashlib.sha256(data).hexdigest()}.get(algo)
                    if actual and c.get("checksumValue") != actual:
                        rep.fail(f"{path}.evidence.packageFileEvidence({algo})",
                                 "evidence checksum mismatch vs disk")
            for le in ev.get("licenseEvidence", []):
                loc = (le.get("evidenceLocation") or "").lstrip("./")
                try:
                    etext = open(loc, encoding="utf-8").read()
                except OSError:
                    rep.fail(f"{path}.evidence.licenseEvidence.evidenceLocation",
                             f"evidence location {loc!r} does not exist on disk")
                    continue
                lic = (le.get("spdxExtractedLicense") or {}).get("licenseId", "")
                if lic and lic not in etext:
                    rep.fail(f"{path}.evidence.licenseEvidence",
                             f"license {lic!r} text not present in evidence location {loc!r}")

    # ---- relationships ----
    for ri, r in enumerate(doc.get("relationships", [])):
        path = f"relationships[{ri}]"
        for field in ("spdxElementId", "relationshipType", "relatedSpdxElement"):
            if not r.get(field):
                rep.fail(f"{path}.{field}", "required field missing")
        if r.get("relationshipType") not in RELATIONSHIP_TYPES:
            rep.fail(f"{path}.relationshipType", f"unknown type {r.get('relationshipType')!r}")
        for ref in ("spdxElementId", "relatedSpdxElement"):
            if r.get(ref) and r[ref] not in all_ids:
                rep.fail(f"{path}.{ref}", f"dangling reference {r[ref]!r}")

    # ---- hasFiles vs files ----
    file_ids = {f.get("SPDXID") for f in files}
    for p in packages:
        for hf in p.get("hasFiles", []):
            if hf not in file_ids:
                rep.fail(f"packages[0].hasFiles", f"references unknown SPDXID {hf!r}")

    # ---- extracted licensing infos ----
    for oi, o in enumerate(doc.get("hasExtractedLicensingInfos", [])):
        path = f"hasExtractedLicensingInfos[{oi}]"
        if not o.get("licenseId"):
            rep.fail(f"{path}.licenseId", "required field missing")
        if not o.get("extractedText"):
            rep.fail(f"{path}.extractedText", "required field missing")
        if o.get("licenseId") in SPDX_LIST_LICENSES:
            rep.warn(f"{path}.licenseId",
                     f"{o['licenseId']} is on the SPDX License List; "
                     "hasExtractedLicensingInfos should only hold non-list licenses")

    # ---- document describes ----
    has_describes = any(
        r.get("relationshipType") == "DESCRIBES" and r.get("spdxElementId") == "SPDXRef-DOCUMENT"
        for r in doc.get("relationships", [])
    ) or bool(doc.get("documentDescribes"))
    if not has_describes and (packages or files):
        rep.warn("document", "no DESCRIBES relationship or documentDescribes pointing at content")

    return rep


def main():
    doc = json.load(open(sys.argv[1]))
    rep = validate(doc)
    rep.print()
    sys.exit(1 if rep.fails else 0)


if __name__ == "__main__":
    main()

